<?php require_once __DIR__.'/../includes/bootstrap.php';require_customer();$cid=(int)$_SESSION['customer_id'];$pdo->prepare('INSERT IGNORE INTO customer_preferences(customer_id) VALUES(?)')->execute([$cid]);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('UPDATE customer_preferences SET email_order_updates=?,email_cart_reminders=?,marketing_email=? WHERE customer_id=?')->execute([!empty($_POST['email_order_updates'])?1:0,!empty($_POST['email_cart_reminders'])?1:0,!empty($_POST['marketing_email'])?1:0,$cid]);$_SESSION['flash']=['type'=>'success','msg'=>'Communication preferences saved.'];redirect('/customer/preferences.php');}$q=$pdo->prepare('SELECT * FROM customer_preferences WHERE customer_id=?');$q->execute([$cid]);$p=$q->fetch();$title='Notification Preferences';require __DIR__.'/../includes/header.php';?><div class="section-head"><div><span class="eyebrow">COMMUNICATION</span><h1>Notification preferences</h1></div></div><section class="panel"><form method="post" class="form"><?=csrf_field()?><label class="check"><input type="checkbox" name="email_order_updates" <?=!empty($p['email_order_updates'])?'checked':''?>> Email me when my order is received or its tracking status changes.</label><label class="check"><input type="checkbox" name="email_cart_reminders" <?=!empty($p['email_cart_reminders'])?'checked':''?>> Email me about products left in my cart for an extended period.</label><label class="check"><input type="checkbox" name="marketing_email" <?=!empty($p['marketing_email'])?'checked':''?>> Send me optional store news and offers.</label><button class="btn primary">Save preferences</button></form></section><?php require __DIR__.'/../includes/footer.php';?>